import json,re
d=json.load(open('snapshot/facts.json'))
def walk(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items():
            yield from walk(v,p+'/'+k)

names=set()
def find(o):
    if isinstance(o,dict):
        for k,v in o.items():
            if re.search(r'Securit|Marketable|Invest|ShortTerm',k): names.add(k)
            find(v)
    elif isinstance(o,list):
        for x in o: find(x)
find(d); print(sorted(names)); print(type(d), list(d)[:5])
